'use strict';

var discreteUniform = require( '@stdlib/random/base/discrete-uniform' );
var filledarrayBy = require( '@stdlib/array/filled-by' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var logEach = require( '@stdlib/console/log-each' );
var zgemv = require( './../lib' );

function rand() {
	return new Complex128( discreteUniform( 0, 10 ), discreteUniform( -5, 5 ) );
}

var x = filledarrayBy( 3, 'complex128', rand );
console.log( x.get( 0 ).toString() );

var y = filledarrayBy( 3, 'complex128', rand );
console.log( y.get( 0 ).toString() );

var A = filledarrayBy( 9, 'complex128', rand );
console.log( A.get( 0 ).toString() );

var alpha = new Complex128( 2.0, 2.0 );
console.log( alpha.toString() );

var beta = new Complex128( 2.0, 2.0 );
console.log( beta.toString() );

// Perform `y = α*A*x + β*y`:
zgemv( 'row-major', 'no-transpose', 3, 3, alpha, A, 3, x, 1, beta, y, 1 );

// Print the results:
logEach( '(%s)', A );

// Perform `y = α*A*x + β*y` using alternative indexing semantics:
zgemv.ndarray( 'no-transpose', 3, 3, alpha, A, 3, 1, 0, x, 1, 0, beta, y, 1, 0 );

// Print the results:
logEach( '(%s)', A );
